transforms.result:
.my-cv {
  position: relative;
  &__initials {
    transition: color ease 1s 1s;
  }
  &__specialization {
    margin-bottom: 12px;
    transition: color ease 1s 1s;
  }
  &__description-row {
    margin-bottom: 4px;
  }
  &__description-key {
    font-weight: 800;
    color: var(--secondary-text-color);
    margin-right: 12px;
    transition: color ease 1s 1s;
    @media screen and (max-width: $tablet) {
      font-size: 16px;
    }
    @media screen and (max-width: $mobile) {
      font-size: 14px;
    }
  }
  &__description-value {
    transition: color ease 1s 1s;
    @media screen and (max-width: $tablet) {
      font-size: 16px;
    }
    @media screen and (max-width: $mobile) {
      font-size: 14px;
    }
  }
  &__description-link {
    width: fit-content;
    border-radius: 4px;
    transition: color, background-color 0.2s ease;
    &:hover {
      background-color: var(--link-hover-color);
      color: var(--item-text-color);
    }
  }
  &__section {
    margin-bottom: 3rem;
  }
  &__switch {
    display: block;
    position: relative;
    width: 42px;
    height: 22px;
    background-color: rgb(110, 110, 110);
    border-radius: 12px;
  }
  &__switch-checked {
    background-color: #c7c7c7;
    & .my-cv__switch-span {
      transform: translate(150%, 0);
      background-color: #0691ff;
    }
    & .my-cv__switch-lang-en {
      display: block;
    }
    & .my-cv__switch-lang-ru {
      display: none;
    }
  }
  &__switch-lang-en {
    display: none;
    position: absolute;
    top: 4px;
    left: 4px;
    color: #1b1b1b;
    line-height: 1;
    font-size: 14px;
    font-weight: 800;
  }
  &__switch-lang-ru {
    display: block;
    position: absolute;
    top: 4px;
    right: 4px;
    color: #fff;
    line-height: 1;
    font-size: 14px;
    font-weight: 800;
  }
  &__switch-span {
    display: block;
    position: absolute;
    left: 0;
    top: 2px;
    background-color: #fff;
    border-radius: 50%;
    width: 17px;
    height: 17px;
    z-index: 1;
  }
  &__switch-input {
    width: 0;
    height: 0;
    appearance: none;
    opacity: 0;
  }
  &__photo {
    position: relative;
  }
  &__profile-photo {
    width: 200px;
    height: 200px;
    border-radius: 50%;
    object-fit: cover;
  }
  &__skill-item {
    padding: 2px 4px;
    background-color: var(--item-background-color);
    color: var(--item-text-color);
    border-radius: 4px;
  }
  &__additional-item {
    width: fit-content;
    padding: 2px 4px;
    box-shadow: 0px 1px 2px 1px #575757;
    border-radius: 4px;
    transition: color, background-color 0.2s ease;
    &:hover {
      background-color: var(--link-hover-color);
      color: var(--item-text-color);
    }
  }

  &__list {
    &_row {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      margin-bottom: 2rem;
    }

    &_column {
      display: flex;
      flex-direction: column;
      gap: 10px;
      margin-bottom: 2rem;
    }
  }
  &__list-item {
    transition: color ease 1s 1s;
    @media screen and (max-width: $tablet) {
      font-size: 16px;
    }
    @media screen and (max-width: $mobile) {
      font-size: 14px;
    }
  }
  &__repos-item {
    display: flex;
    flex-wrap: wrap;
    @media screen and (max-width: $tablet) {
      flex-direction: column;
      align-items: center;
    }
  }
  &__item-inner {
    display: flex;
    flex-wrap: wrap;
    @media screen and (max-width: $mobile) {
      flex-direction: column;
      align-items: center;
    }
  }
  &__my-repos {
    margin-bottom: 12px;
    padding: 4px;
    cursor: pointer;
    transition: color 0.2s linear;
    width: fit-content;
    transition: color, background-color 0.2s linear;
    border-radius: 4px;
    &:hover {
      color: var(--item-text-color);
      background-color: var(--item-background-color);
    }
  }
  &__my-portfolio {
    margin-bottom: 12px;
  }
  &__test-tasks {
    margin-bottom: 12px;
  }
}
.block {
  &__primal,
  &__secondary,
  &__alternate {
    padding: 4px 2px;
    color: var(--item-text-color);
    border-radius: 4px;
  }
  &__primal {
    background-color: var(--primal-background-color);
  }
  &__secondary {
    background-color: var(--secondary-background-color);
  }
  &__alternate {
    background-color: var(--alternate-background-color);
  }
}
.repos-table,
.portfolio-table,
.test-tasks {
  display: flex;
  flex-direction: column;
  width: 100%;
  margin-bottom: 28px;
  &__row {
    display: flex;
    width: 100%;
    margin-bottom: 8px;
    border-bottom: 1px solid var(--main-text-color);
  }
  &__cell,
  &__header-cell {
    display: block;
    padding-left: 4px;
    padding-right: 4px;
    padding-bottom: 8px;
    flex: 1 1 auto;
    min-width: 20px;
    max-width: 24%;
    @media screen and (max-width: $tablet) {
      min-width: 60px;
      font-size: 13px;
    }
    @media screen and (max-width: $mobile) {
      min-width: 40px;
      font-size: 12px;
    }
  }
}
.test-tasks {
  &__cell {
    max-width: 20%;
  }
}
.cell {
  &__default {
    min-width: 120px;
    transition: color ease 1s 1s;
    @media screen and (max-width: $tablet) {
      min-width: 70px;
    }
    @media screen and (max-width: $mobile) {
      min-width: 40px;
    }
  }
  &__text {
    min-width: 120px;
    transition: color ease 1s 1s;

    @media screen and (max-width: $tablet) {
      min-width: 70px;
    }
    @media screen and (max-width: $mobile) {
      min-width: 40px;
    }
  }
  &__name {
    min-width: 160px;
    transition: color ease 1s 1s;
    padding: 2px 4px;
    box-shadow: 0px 1px 2px 1px #575757;
    border-radius: 4px;
    transition: color, background-color 0.2s ease;
    &:hover {
      background-color: var(--link-hover-color);
      color: var(--item-text-color);
    }
    @media (hover: none) {
      background-color: transparent;
      color: var(--main-text-color);
    }
    @media screen and (max-width: $tablet) {
      min-width: 100px;
    }
    @media screen and (max-width: $mobile) {
      min-width: 60px;
    }
  }
  &__language {
    // max-width: 100px;
    text-align: center;
    transition: color ease 1s 1s;
  }
  &__language-text {
    display: inline-block;
    width: fit-content;
    text-align: center;
    padding: 2px 4px;
    border-radius: 4px;
    filter: brightness(1.3);
  }
  &__created {
    max-width: 100px;
    text-align: center;
    transition: color ease 1s 1s;
  }
  &__description {
    min-width: 120px;
    transition: color ease 1s 1s;
    @media screen and (max-width: $tablet) {
      min-width: 100px;
    }
    @media screen and (max-width: $mobile) {
      min-width: 60px;
    }
  }
  &__link {
    display: block;
    padding: 2px 4px;
    max-width: 80%;
    width: fit-content;
    border-radius: 4px;
    text-overflow: ellipsis;
    overflow: hidden;
    white-space: nowrap;
    transition: color, background-color 0.2s ease;
    cursor: pointer;
    box-shadow: 0px 1px 2px 1px #575757;
    border-radius: 4px;
    &:hover {
      background-color: var(--link-hover-color);
      color: var(--item-text-color);
    }
    @media (hover: none) {
      background-color: transparent;
      color: var(--main-text-color);
    }
    &:hover {
      background-color: var(--link-hover-color);
      color: var(--item-text-color);
    }
  }
}
.word-break {
  word-break: break-all;
}
.hide-to-mobile {
  @media screen and (max-width: 480px) {
    display: none;
  }
}
